import { useState } from 'react';

function Contador() {
  const [numero, setNumero] = useState(0);
  return <div>
    <p>Valor: {numero}</p>
    <button onClick={() => setNumero(numero + 1)}>Sumar</button>
    <button onClick={() => setNumero(0)}>Reiniciar</button>
  </div>;
}

function ContadorRapido() {
  const [numero, setNumero] = useState(0);
  function sumarTres() {
    setNumero(actual => actual + 1);
    setNumero(actual => actual + 1);
    setNumero(actual => actual + 1);
  }
  return <button onClick={sumarTres}>Sumar tres: {numero}</button>;
}

function Perfil() {
  const [usuario, setUsuario] = useState({ nombre: 'Ana', ciudad: 'Corrientes' });
  function cambiarCiudad() {
    setUsuario(actual => ({ ...actual, ciudad: 'Resistencia' }));
  }
  return <div>
    <p>{usuario.nombre} — {usuario.ciudad}</p>
    <button onClick={cambiarCiudad}>Cambiar ciudad</button>
  </div>;
}

function ListaTareas() {
  const [tareas, setTareas] = useState(['Leer']);
  function agregar() {
    setTareas(actuales => [...actuales, 'Practicar']);
