customElements.define('mi-boton-registro', MiBotonRegistro);

class MiTitulo extends HTMLElement {
  static observedAttributes = ['titulo'];

  connectedCallback() {
    this.actualizar();
  }

  attributeChangedCallback(nombre, valorAnterior, valorNuevo) {
    if (valorAnterior !== valorNuevo && this.isConnected) {
      this.actualizar();
    }
  }

  actualizar() {
    this.textContent = this.getAttribute('titulo') || 'Título sin definir';
  }
}

customElements.define('mi-titulo', MiTitulo);

// HTML: <mi-titulo titulo="Primer título"></mi-titulo>
