class MiCronometro extends HTMLElement {
  constructor() {
    super();
    this.segundos = 0;
    this.intervalo = null;
  }

  connectedCallback() {
    if (this.intervalo !== null) return;
    this.intervalo = setInterval(() => {
      this.segundos += 1;
      this.textContent = 'Segundos: ' + this.segundos;
    }, 1000);
  }

  disconnectedCallback() {
    clearInterval(this.intervalo);
    this.intervalo = null;
  }
}

customElements.define('mi-cronometro', MiCronometro);

