class MiListaSlots extends HTMLElement {
  constructor() {
    super();
    const root = this.attachShadow({ mode: 'open' });
    root.innerHTML = '<section><slot name="item"></slot><p id="cantidad"></p></section>';
    const slot = root.querySelector('slot');
    const salida = root.querySelector('#cantidad');
    const actualizar = () => {
      salida.textContent = 'Elementos asignados: ' + slot.assignedElements().length;
    };
    slot.addEventListener('slotchange', actualizar);
    actualizar();
  }
}

