class MiAccionCancelable extends HTMLElement {
  connectedCallback() {
    this.textContent = 'Intentar eliminar';
    this.addEventListener('click', () => {
      const permitido = this.dispatchEvent(new CustomEvent('antes-de-eliminar', {
        detail: { id: 17 },
        bubbles: true,
        cancelable: true
      }));

